#include<bits/stdc++.h>
using namespace std;
const int mod = 998244353;
int add(int x, int y) {
    return x + y - (x + y >= mod) * mod;
}
void add2(int &x, int y) {
    x += y;
    if (x >= mod) x -= mod;
}
int mul(int x, int y) {
    return int((int64_t)x * y % mod);
}
int sub(int x, int y) {
    return x - y + (x < y) * mod;
}
void sub2(int &x, int y) {
    x -= y;
    if (x < 0) x += mod;
}
int pwr(int x, int y) {
    int ret = 1;
    while (y) {
        if (y & 1) ret = mul(ret, x);
        x = mul(x, x);
        y /= 2;
    }
    return ret;
}
int inv(int x) {
    return pwr(x, mod - 2);
}
int norm(int64_t x) {
    x %= mod;
    if (x < 0) x += mod;
    return int(x);
}
void solve() {
    int n;
    cin >> n;
    vector adj(n + 1, vector<int> ());
    vector<int> p(n + 1);
    for (int i = 1; i <= n; i++) {
        int q;
        cin >> p[i] >> q;
        p[i] = mul(p[i], inv(q));
        //here, p[i] is the probability that node i will fall
    }
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v), adj[v].push_back(u);
    }
    vector<int> p1(n + 1), p2(n + 1);
    for (int i = 1; i <= n; i++) {
        p1[i] = sub(1, p[i]);
        for (int u: adj[i]) {
            p1[i] = mul(p1[i], p[u]);
        }
        //p1[i] is the probability that node i won't fall, but all nodes around it will fall
        for (int u: adj[i]) {
            add2(p2[i], mul(p1[i], mul(inv(p[u]), sub(1, p[u]))));
        }
        //p2[i] is the probability that node i will be a leaf (it won't fall, all it's neighbors except one will fall)
    }
    int ans = 0, sum = 0;
    for (int i = 1; i <= n; i++) {
        add2(ans, mul(p2[i], sum));
        add2(sum, p2[i]);
    }
    //take all contributions of unordered pairs 
    for (int i = 1; i <= n; i++) {
        //recalculate the contribution of neighboring pairs 
        for (auto u: adj[i]) {
            if (u < i) continue;
            //avoid calculating the same pair probabilty twice
            int pi = mul(p1[i], inv(p[u]));
            //pi is the probability that every neighbour of i would fall except for u (not including the probability of u not falling down)
            int pu = mul(p1[u], inv(p[i]));
            //pu is the probability that every neighbour of u would fall except for i (not including the probability of i not falling down)
            //this case is just a tree of 2 nodes, both of them are leaves
            add2(ans, mul(pi, pu));
            //subtract the old contribution
            sub2(ans, mul(p2[i], p2[u]));
        }
        //recalculate the contribution of pairs with a shared neighbour which is node i (ie calculate the contribution for pairs u, v such that dis(u, v) = 2 and dis(u, i) = dis(v, i) = 1
        sum = 0;
        for (int u: adj[i]) {
            sub2(ans, mul(sum, p2[u]));
            add2(sum, p2[u]);
            //subtract the old contribution 
        }
        //p[i] doesn't fall
        sum = 0;
        for (int u: adj[i]) {
            int pu = mul(p1[u], inv(p[i]));
            //pu is the probability that node u is a leaf connected to node i
            add2(ans, mul(sum, pu));
            add2(sum, mul(pu, sub(1, p[i])));
        }
        //p[i] falls
        sum = 0;
        for (int u: adj[i]) {
            int pu = sub(p2[u], mul(p1[u], mul(inv(p[i]), sub(1, p[i]))));
            //pu is the probability that node u is a leaf not connected to node i
            add2(ans, mul(sum, pu));
            add2(sum, mul(pu, inv(p[i])));
        }
    }
    cout << ans << "\n";
}
int main() {
    ios::sync_with_stdio(0), cin.tie(0);
    int tt = 1;
    cin >> tt;
    while (tt--) {
        solve();
    }
}

Problem B:
[Statement]
[Problem]
This is the hard version of the problem. The difference between the versions is that in this version, there are no additional limits on $k$. You can hack only if you solved all versions of this problem. Ecrade has two sequences $a_0, a_1, \ldots, a_{n - 1}$ and $b_0, b_1, \ldots, b_{n - 1}$ consisting of integers. It is guaranteed that the sum of all elements in $a$ does not exceed the sum of all elements in $b$. Initially, Ecrade can make exactly $k$ changes to the sequence $a$. It is guaranteed that $k$ does not exceed the sum of $a$. In each change: Choose an integer $i$ ($0 \le i \lt n$) such that $a_i \gt 0$, and perform $a_i := a_i - 1$. Then Ecrade will perform the following three operations sequentially on $a$ and $b$, which constitutes one round of operations: For each $0 \le i \lt n$: $t := \min(a_i, b_i), a_i := a_i - t, b_i := b_i - t$; For each $0 \le i \lt n$: $c_i := a_{(i - 1) \bmod n}$; For each $0 \le i \lt n$: $a_i := c_i$; Ecrade wants to know the minimum number of rounds required for all elements in $a$ to become equal to $0$ after exactly $k$ changes to $a$. However, this seems a bit complicated, so please help him!

[Input]
Each test contains multiple test cases. The first line contains the number of test cases $t$ ($1 \le t \le 2\cdot 10^4$). The description of the test cases follows. The first line of each test case contains two integers $n$, $k$ ($1\le n\le 2\cdot 10^5$, $0\le k\le 2\cdot 10^{14}$). The second line of each test case contains $n$ integers $a_0, a_1, \ldots, a_{n - 1}$ ($1 \le a_i \le 10^9$). The third line of each test case contains $n$ integers $b_0, b_1, \ldots, b_{n - 1}$ ($1 \le b_i \le 10^9$). It is guaranteed that the sum of $n$ across all test cases does not exceed $2\cdot 10^5$. It is also guaranteed that in each test case the sum of $a$ does not exceed the sum of $b$, and that $k$ does not exceed the sum of $a$.

[Output]
For each test case, output the minimum number of rounds required for all elements in $a$ to become equal to $0$ after exactly $k$ changes to $a$.

[Note]
In the fifth test case, all elements in $a$ become $0$ after exactly $6$ changes. In the sixth test case, Ecrade can do exactly one change to $a_3$, then $a$ will become $[1,2,2,4]$. After the first round, $a=[3,0,0,0],b=[3,1,0,0]$; After the second round, $a=[0,0,0,0],b=[0,1,0,0]$. In the seventh test case, Ecrade can do exactly one change to $a_4$, then $a$ will become $[2,1,1,1]$. After the first round, $a=[0,1,0,0],b=[0,1,1,0]$; After the second round, $a=[0,0,0,0],b=[0,0,1,0]$.

