#include <cstdio>
#include <queue>

using namespace std;

const int N = 2e5 + 5;

int n, k;
int d[N];
long long ans;

void solve() {
	scanf("%d%d", &n, &k);
	ans = 0;
	priority_queue <int> q;
	for (int i = 1; i <= n; i++) {
		scanf("%d", &d[i]);
		q.push(d[i]);
		if ((n - i + 1) % (k + 1) == 0) {
			ans += q.top();
			q.pop();
		}
	}
	printf("%lld\n", ans);
}

