getint = lambda: int(input())
getints = lambda: map(int, input().split())

def solve():
	n = getint()
	a = list(getints())
	op = []
	mid, r = n // 2, n
	if 0 in a[mid:]:
		op.append([mid + 1, n])
		r -= n - mid - 1
	if 0 in a[:mid]:
		op.append([1, mid])
		r -= mid - 1
	op.append([1, r])
	print(len(op))
	for o in op:
		print(*o)

t = getint()
for _ in range(t):
	solve()

