#include<bits/stdc++.h>
using namespace std;
const int mod = 998244353;
int add(int x, int y) {
    return x + y - (x + y >= mod) * mod;
}
void add2(int &x, int y) {
    x += y;
    if (x >= mod) x -= mod;
}
int mul(int x, int y) {
    return int((int64_t)x * y % mod);
}
int sub(int x, int y) {
    return x - y + (x < y) * mod;
}
void sub2(int &x, int y) {
    x -= y;
    if (x < 0) x += mod;
}
int pwr(int x, int y) {
    int ret = 1;
    while (y) {
        if (y & 1) ret = mul(ret, x);
        x = mul(x, x);
        y /= 2;
    }
    return ret;
}
int inv(int x) {
    return pwr(x, mod - 2);
}
int norm(int64_t x) {
    x %= mod;
    if (x < 0) x += mod;
    return int(x);
}
void solve() {
    int n;
    cin >> n;
    vector adj(n + 1, vector<int> ());
    vector<int> p(n + 1);
    for (int i = 1; i <= n; i++) {
        int q;
        cin >> p[i] >> q;
        p[i] = mul(p[i], inv(q));
        //here, p[i] is the probability that node i will fall
    }
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v), adj[v].push_back(u);
    }
    vector<int> p1(n + 1), p2(n + 1);
    for (int i = 1; i <= n; i++) {
        p1[i] = sub(1, p[i]);
        for (int u: adj[i]) {
            p1[i] = mul(p1[i], p[u]);
        }
        //p1[i] is the probability that node i won't fall, but all nodes around it will fall
        for (int u: adj[i]) {
            add2(p2[i], mul(p1[i], mul(inv(p[u]), sub(1, p[u]))));
        }
        //p2[i] is the probability that node i will be a leaf (it won't fall, all it's neighbors except one will fall)
    }
    int ans = 0, sum = 0;
    for (int i = 1; i <= n; i++) {
        add2(ans, mul(p2[i], sum));
        add2(sum, p2[i]);
    }
    //take all contributions of unordered pairs 
    for (int i = 1; i <= n; i++) {
        //recalculate the contribution of neighboring pairs 
        for (auto u: adj[i]) {
            if (u < i) continue;
            //avoid calculating the same pair probabilty twice
            int pi = mul(p1[i], inv(p[u]));
            //pi is the probability that every neighbour of i would fall except for u (not including the probability of u not falling down)
            int pu = mul(p1[u], inv(p[i]));
            //pu is the probability that every neighbour of u would fall except for i (not including the probability of i not falling down)
            //this case is just a tree of 2 nodes, both of them are leaves
            add2(ans, mul(pi, pu));
            //subtract the old contribution
            sub2(ans, mul(p2[i], p2[u]));
        }
        //recalculate the contribution of pairs with a shared neighbour which is node i (ie calculate the contribution for pairs u, v such that dis(u, v) = 2 and dis(u, i) = dis(v, i) = 1
        sum = 0;
        for (int u: adj[i]) {
            sub2(ans, mul(sum, p2[u]));
            add2(sum, p2[u]);
            //subtract the old contribution 
        }
        //p[i] doesn't fall
        sum = 0;
        for (int u: adj[i]) {
            int pu = mul(p1[u], inv(p[i]));
            //pu is the probability that node u is a leaf connected to node i
            add2(ans, mul(sum, pu));
            add2(sum, mul(pu, sub(1, p[i])));
        }
        //p[i] falls
        sum = 0;
        for (int u: adj[i]) {
            int pu = sub(p2[u], mul(p1[u], mul(inv(p[i]), sub(1, p[i]))));
            //pu is the probability that node u is a leaf not connected to node i
            add2(ans, mul(sum, pu));
            add2(sum, mul(pu, inv(p[i])));
        }
    }
    cout << ans << "\n";
}
int main() {
    ios::sync_with_stdio(0), cin.tie(0);
    int tt = 1;
    cin >> tt;
    while (tt--) {
        solve();
    }
}

Problem A:
[Statement]
[Problem]
The pink soldiers have given you a sequence $a$ consisting of $n$ positive integers. You must repeatedly perform the following operation until there is only $1$ element left. Choose two distinct indices $i$ and $j$. Then, choose a positive integer value $x$ such that there exists a non-degenerate triangle$^{\text{∗}}$ with side lengths $a_i$, $a_j$, and $x$. Finally, remove two elements $a_i$ and $a_j$, and append $x$ to the end of $a$. Please find the maximum possible value of the only last element in the sequence $a$. $^{\text{∗}}$A triangle with side lengths $a$, $b$, $c$ is non-degenerate when $a+b \gt c$, $a+c \gt b$, $b+c \gt a$.

[Input]
Each test contains multiple test cases. The first line contains the number of test cases $t$ ($1 \le t \le 10^4$). The description of the test cases follows. The first line of each test case contains a single integer $n$ ($1 \le n \le 2 \cdot 10^5$). The second line of each test case contains $n$ integers $a_1,a_2,\ldots,a_n$ ($1 \le a_i \le 1000$) — the elements of the sequence $a$. It is guaranteed that the sum of $n$ over all test cases does not exceed $2 \cdot 10^5$.

[Output]
For each test case, output the maximum possible value of the only last element on a separate line.

[Note]
On the first test case, there is already only one element. The value of the only last element is $10$. On the second test case, $a$ is initially $[998,244,353]$. The following series of operations is valid: Erase $a_2=244$ and $a_3=353$, and append $596$ to the end of $a$. $a$ is now $[998,596]$. Erase $a_1=998$ and $a_2=596$, and append $1593$ to the end of $a$. $a$ is now $[1593]$. It can be shown that the only last element cannot be greater than $1593$. Therefore, the answer is $1593$.

