#include<bits/stdc++.h>
char s[333333];
char val(char x,char y,char z){
	return x=='1'?y:z;
}
std::pair<std::string, char> fold(int l,int r){
	std::string str;
	char v=s[r];
	for(int i=l;i<r;i+=2){
		str+=s[i];
		str+='?';
		str+=s[i+1];
		str+=':';
	}
	str+=s[r];
	for(int i=r-2;i>=l;i-=2){
		v=val(s[i],s[i+1],v);
	}
	return std::make_pair(str,v);
}
void solve(){
	int n;
	scanf("%d",&n);
	n=2*n+1;
	scanf("%s",s+1);
	int last=0;
	for(int i=1;i<=n;++i){
		if(s[i]=='1'&&last>0){
			if(i%2==0&&last&1){
				puts("Yes");
				std::string s4=fold(last+1,i).first;
				auto tmp=fold(i+1,n);
				std::string s5=tmp.first;
				char v5=tmp.second;
				if(last==1){
					printf("1?(%s):(%s)\n",s4.c_str(),s5.c_str());
					return;
				}
				tmp=fold(1,last-2);
				std::string s1=tmp.first;
				char v1=tmp.second;
				if(v1=='1'){
					printf("(%s)?(%c?1:(%s)):(%s)\n",s1.c_str(),s[last-1],s4.c_str(),s5.c_str());
				}
				else{
					printf("((%s)?%c:1)?(%s):(%s)\n",s1.c_str(),s[last-1],s4.c_str(),s5.c_str());
				}
				return;
			}
		}
		if(s[i]=='1'){
			last=i;
		}
	}
	if(s[n]=='1'&&std::string(s+1)!="101"){
		puts("Yes");
		auto left=s[1]=='0'?fold(1,1):fold(1,3);
		auto mid=s[1]=='0'?fold(2,n-1):fold(4,n-1);
		printf("(%s)?(%s):1\n",left.first.c_str(),mid.first.c_str());
		return;
	}
	puts("No");
	return;
}
int main(){
	int T;
	scanf("%d",&T);
	while(T--){
		solve();
	}
	return 0;
}

