#include <iostream>
#include <vector>

using namespace std;

using ll = long long;

void solve() {
    int n; cin >> n;
    string s; cin >> s;
    vector <int> a;
    int curr = 0;
    for (int i = 0; i < n; ++i) {
        if (i && s[i] != s[i - 1]) {
            if (curr) a.push_back(curr);
            curr = 1;
        }
        else ++curr;
    }
    a.push_back(curr);
    int sz = a.size();

    vector <int> ans(n, 0), left(sz, 0), right(sz, 0);
    for (int i = 0; i < sz; ++i) {
        if (!i) {
            left[i] = 0; right[i] = a[i] - 1;
        } else {
            left[i] = right[i - 1] + 1;
            right[i] = left[i] + a[i] - 1;
        }
    }
    for (int i = 0; i < sz; ++i) {
        for (int j = left[i]; j <= right[i]; ++j) {
            ans[j] += j - i + 1;
        }
    }
    vector <int> add(sz, 0);
    for (int m = 1; m < sz; ++m) {
        ll l = m, r = m, k = 1;
        while (l < sz) {
            ++add[l];
            if (r + 1 < sz) --add[r + 1];

            if (a[l] == 1) {
                l += m + 1;
            } else {
                l += m;
            }

            r += m + 1;
            ++k;
        }
    }
    int pref = 0;
    for (int i = 0; i < sz; ++i) {
        pref += add[i];
        for (int j = left[i]; j <= right[i]; ++j) {
            ans[j] += pref;
        }
    }
    for (int i = 0; i < n; ++i) {
        cout << ans[i];
        if (i != n - 1) cout << ' ';
    }
    cout << '\n';
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    int t; cin >> t;
    while (t--) {
        solve();
    }
}

