#include <iostream>
#include <vector>

using namespace std;

using ll = long long;

void solve() {
    int n; cin >> n;
    string s; cin >> s;
    vector <int> a;
    int curr = 0;
    for (int i = 0; i < n; ++i) {
        if (i && s[i] != s[i - 1]) {
            if (curr) a.push_back(curr);
            curr = 1;
        }
        else ++curr;
    }
    a.push_back(curr);
    int sz = a.size();

    vector <int> ans(n, 0), left(sz, 0), right(sz, 0);
    for (int i = 0; i < sz; ++i) {
        if (!i) {
            left[i] = 0; right[i] = a[i] - 1;
        } else {
            left[i] = right[i - 1] + 1;
            right[i] = left[i] + a[i] - 1;
        }
    }
    for (int i = 0; i < sz; ++i) {
        for (int j = left[i]; j <= right[i]; ++j) {
            ans[j] += j - i + 1;
        }
    }
    vector <int> add(sz, 0);
    for (int m = 1; m < sz; ++m) {
        ll l = m, r = m, k = 1;
        while (l < sz) {
            ++add[l];
            if (r + 1 < sz) --add[r + 1];

            if (a[l] == 1) {
                l += m + 1;
            } else {
                l += m;
            }

            r += m + 1;
            ++k;
        }
    }
    int pref = 0;
    for (int i = 0; i < sz; ++i) {
        pref += add[i];
        for (int j = left[i]; j <= right[i]; ++j) {
            ans[j] += pref;
        }
    }
    for (int i = 0; i < n; ++i) {
        cout << ans[i];
        if (i != n - 1) cout << ' ';
    }
    cout << '\n';
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    int t; cin >> t;
    while (t--) {
        solve();
    }
}

Problem A:
[Statement]
[Problem]
Suppose you have two arrays $c$ and $d$, each of length $k$. The pair $(c, d)$ is called good if $c$ can be changed to $d$ by performing the following operation any number of times. Select two distinct indices $i$ and $j$ ($1 \leq i, j \leq k$, $i \neq j$) and a nonnegative integer $x$ ($0 \leq x \lt 2^{30}$). Then, apply the following transformations: $c_i := c_i \mathbin{\&} x$, where $\&$ denotes the bitwise AND operation. $c_j := c_j \mathbin{|} x$, where $|$ denotes the bitwise OR operation. You are given two arrays $a$ and $b$, both of length $n$, containing nonnegative integers not exceeding $m$. You can perform two types of moves on these arrays any number of times: Select an index $i$ ($1 \leq i \leq n$) and set $a_i := a_i + 1$. Select an index $i$ ($1 \leq i \leq n$) and set $b_i := b_i + 1$. Note that the elements of $a$ and $b$ may exceed $m$ at some point while performing the moves. Find the minimum number of moves required to make the pair $(a, b)$ good.

[Input]
Each test contains multiple test cases. The first line contains the number of test cases $t$ ($1 \le t \le 10^4$). The description of the test cases follows. The first line of each test case contains two integers $n$ and $m$ ($1 \leq n, m \leq 2 \cdot 10^6$) — the length of arrays $a$ and $b$, and the maximum possible value in these arrays, respectively. The second line contains $n$ integers $a_1, a_2, \ldots, a_n$ ($0 \leq a_i \leq m$) — denoting the array $a$. The third line contains $n$ integers $b_1, b_2, \ldots, b_n$ ($0 \leq b_i \leq m$) — denoting the array $b$. Additionally, it is guaranteed that the sum of all values of $n$ and the sum of all values of $m$ across all test cases do not exceed $2 \cdot 10^6$.

[Output]
For each test case, output a single integer — the minimum number of moves required to make the pair $(a, b)$ good.

[Note]
