[Editorial]
2085E - Serval and Modulo Hint 1 What happens when an integer $a_i$ mods $k$? Hint 2 Note that the difference between $a_i$ and $b_i$ is a multiple of $k$. Hint 3 The same holds for the difference between the sum of $a_i$ and the sum of $b_i$. Hint 4 Notice that $d(n) \leq 2304$ holds for all $n \leq 10^{10}$, where $d(n)$ denotes the number of divisors of $n$. Solution Note that if such a magic number $k$ exists, it will be a divisor of $\Delta = \sum a_i - \sum b_i$ when $\Delta \neq 0$, or it can be any integer greater than all the $a_i$. Thus, we can check all the divisors of $\Delta$, resulting in a solution of $O\left(\sum (n \cdot d(\sum a_i) + \sqrt{\sum a_i})\right)$ time, where $d(n)$ denotes the number of divisors of $n$. Code (C++)

[Reference solution]
#include <cstdio>

using namespace std;

const int N = 1e4 + 5;
const int C = 1e6 + 5;

int n;
int a[N], b[N];
int cnt[C];
long long s;

bool check(int k) {
	for (int i = 1; i <= n; i++)
		cnt[a[i] % k]++;
	for (int i = 1; i <= n; i++)
		if (--cnt[b[i]] < 0) {
			cnt[b[i]] = 0;
			for (int i = 1; i <= n; i++)
				cnt[a[i] % k] = 0;
			return 0;
		}
	return 1;
}

void solve() {
	scanf("%d", &n);
	s = 0;
	for (int i = 1; i <= n; i++) {
		scanf("%d", &a[i]);
		s += a[i];
	}
	for (int i = 1; i <= n; i++) {
		scanf("%d", &b[i]);
		s -= b[i];
	}
	if (s == 0) {
		printf("%d\n", check(0xc0ffee) ? 0xc0ffee : -1);
		return;
	}
	for (int i = 1; 1ll * i * i <= s; i++)
		if (s % i == 0) {
			if (check(i)) {
				printf("%d\n", i);
				return;
			}
			if (i < C && check(s / i)) {
				printf("%d\n", (int)(s / i));
				return;
			}
		}
	printf("-1\n");
}

int main() {
	int t;
	scanf("%d", &t);
	while (t--)
		solve();
	return 0;
}

